import sys
def main():
    s = sys.stdin.buffer.read().decode().rstrip("\r\n")
    pair = {")": "(", "]": "["}
    st = []
    for ch in s:
        if ch in "([":
            st.append(ch)
        else:
            if not st or st[-1] != pair[ch]:
                print("No"); return
            st.pop()
    print("Yes" if not st else "No")
main()
